'use strict';
/* SwiftDrop offline single-file bundler.
 * Packs server.js + the whole web app into ONE self-contained JS file
 * (offline-server.js) that runs with plain `node offline-server.js`:
 *  - needs NO internet, NO npm install, NO cloud, NO public/ folder
 *  - perfect for hosting from an Android phone (Termux) or a PC over
 *    the same WiFi / hotspot.
 *
 * Usage:  node tools/bundle-offline.js
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');

function read(p) {
  return fs.readFileSync(path.join(ROOT, p), 'utf8');
}

function buildSingleHtml() {
  let html = read('public/index.html');
  const css = read('public/styles.css');
  const js = read('public/client.js');
  const qr = read('public/vendor/qrcode.js');

  html = html.replace(/<link rel="manifest"[^>]*>\s*/g, '');
  html = html.replace(/<link rel="stylesheet"[^>]*>\s*/g, '<style>\n' + css + '\n</style>');
  html = html.replace(/<script src="vendor\/qrcode\.js[^>]*><\/script>\s*/g, '<script>\n' + qr + '\n</script>');
  html = html.replace(/<script src="client\.js[^>]*><\/script>\s*/g, '<script>\n' + js + '\n</script>');
  return html;
}

function build() {
  const html = buildSingleHtml();
  const serverSrc = read('server.js');
  const htmlB64 = Buffer.from(html, 'utf8').toString('base64');
  const serverJson = JSON.stringify(serverSrc);

  const out = [
    "'use strict';",
    '/* ============================================================',
    '   SwiftDrop — OFFLINE single-file server',
    '   Generated by tools/bundle-offline.js — do not edit by hand.',
    '',
    '   Runs the FULL app (page + WebSocket signaling + relay) from',
    '   one file. No internet, no npm install, no public/ folder.',
    '',
    '   On Windows / Mac / Linux:     node offline-server.js',
    '   On Android (Termux):          node offline-server.js',
    '',
    '   Then open the printed Network URL (http://your-ip:3000) on the',
    '   other phone — both phones must be on the same WiFi or hotspot.',
    '   ============================================================ */',
    '',
    'if (global.__SD_BUNDLED_HTML_B64 !== undefined) {',
    "  throw new Error('This file is meant to run on its own, not be required.');",
    '}',
    'global.__SD_BUNDLED_HTML_B64 = ' + JSON.stringify(htmlB64) + ';',
    '',
    '// ---- load the real server implementation ----',
    'const __serverSource = ' + serverJson + ';',
    'const __mod = { exports: {} };',
    "const __run = new Function('require', 'module', 'exports', '__dirname', '__filename', __serverSource);",
    '__run(require, __mod, __mod.exports, __dirname, __filename);',
    'module.exports = __mod.exports;',
    ''
  ].join('\n');

  const dest = path.join(ROOT, 'offline-server.js');
  fs.writeFileSync(dest, out, 'utf8');
  console.log('bundled ->', dest, (Buffer.byteLength(out) / 1024).toFixed(1) + ' KB');
}

build();